// EDIT THESE — then the rest of the workflow needs no changes.
// actionSecret MUST equal ACTION_SECRET in the Revive backend .env
// glmKey = your OpenRouter API key (sk-or-v1-...)
// glmModel = 'openrouter/free' or any slug from https://openrouter.ai/models
return [{ json: {
  reviveApiBase: 'https://revivepropertyco.au/api/hipages',
  actionSecret: 'REPLACE_WITH_ACTION_SECRET',
  glmUrl: 'https://openrouter.ai/api/v1/chat/completions',
  glmModel: 'openrouter/free',
  glmKey: 'REPLACE_WITH_OPENROUTER_API_KEY',
  minConfidence: 0.7
} }];

const body = $input.first().json;
const rows = Array.isArray(body.data) ? body.data : [];
return rows.map(r => ({ json: r }));

const cfg = $('Config').first().json;
const lead = $json;
const hay = `${lead.job_type||''} ${lead.job_subtype||''} ${lead.description||''}`.toLowerCase();
const KW = ['pressure','jet wash','jetwash','jet-wash','driveway','patio','paving','path clean','fence clean','soft wash','house wash','exterior clean','exterior wash','roof clean','mould','mold','algae','grout','regrout','re-grout','tile','tiling','epoxy'];
const prefilter = KW.some(k => hay.includes(k));
let decision = 'skip', service_line = 'none', confidence = 0, reason = 'prefilter: no target keywords';
if (prefilter) {
  const sys = "You are a lead-qualification classifier for Revive Property Co, an Australian property-services business. Revive ONLY wants two job kinds: (1) pressure_washing = exterior / hard-surface cleaning (pressure or jet washing, driveways, paths, patios, paving, fences, house or building exterior wash, soft wash, roof cleaning, mould/algae/grime removal from hard surfaces); (2) regrouting = tile grout work (regrouting, grout repair or restoration, tile and grout cleaning or resealing, shower or bathroom grout, epoxy grout). Everything else (handyman, furniture, gardening, landscaping, plumbing, electrical, painting, waterproofing, installing NEW tiles, building) is none. Respond with ONLY a compact JSON object, no prose and no code fences: {\"match\": boolean, \"service_line\": \"pressure_washing\"|\"regrouting\"|\"none\", \"confidence\": number between 0 and 1, \"reason\": short string}. Set match true only if service_line is pressure_washing or regrouting.";
  const usr = JSON.stringify({ job_type: lead.job_type, job_subtype: lead.job_subtype, description: lead.description, suburb: lead.suburb });
  let parsed = { match: false, service_line: 'none', confidence: 0, reason: 'no_response' };
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST', url: cfg.glmUrl,
      headers: { Authorization: `Bearer ${cfg.glmKey}`, 'Content-Type': 'application/json' },
      body: { model: cfg.glmModel, temperature: 0, messages: [ { role: 'system', content: sys }, { role: 'user', content: usr } ] },
      json: true
    });
    const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '{}';
    const jsonStr = String(content).replace(/```json/gi, '').replace(/```/g, '').trim();
    try { parsed = JSON.parse(jsonStr); } catch (e) { parsed = { match: false, service_line: 'none', confidence: 0, reason: 'parse_error: ' + String(content).slice(0, 120) }; }
  } catch (e) {
    parsed = { match: false, service_line: 'none', confidence: 0, reason: 'glm_error: ' + String(e.message || e).slice(0, 120) };
  }
  service_line = parsed.service_line || 'none';
  confidence = Number(parsed.confidence) || 0;
  reason = parsed.reason || '';
  const isMatch = !!parsed.match && (service_line === 'pressure_washing' || service_line === 'regrouting');
  decision = (isMatch && confidence >= Number(cfg.minConfidence || 0)) ? 'accept' : 'skip';
}
return { json: { opportunityId: lead.crm_opportunity_id, decision, service_line, confidence, reason, lead_id: lead.lead_id, job_type: lead.job_type, suburb: lead.suburb, credits: lead.credits } };
